"""Validation and unit conversion for batches of rows."""

import math


def _valid_amount(value):
    """Return whether value is a finite, nonnegative int or float."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return False
    if value < 0:
        return False
    # Every Python int is finite. Calling math.isfinite on an extremely large
    # int attempts a float conversion and can raise OverflowError.
    return isinstance(value, int) or math.isfinite(value)


def evaluate(request, policy):
    """Validate rows and convert accepted amounts to the base unit."""
    errors = []
    records = []
    seen_ids = set()
    unique = policy.get("unique", False)
    units = policy["units"]
    base_unit = policy["base_unit"]

    for index, row in enumerate(request["rows"]):
        row_id = row.get("id")
        if not isinstance(row_id, str) or not row_id:
            errors.append({"row": index, "cause": "id"})
            continue

        duplicate = unique and row_id in seen_ids
        if unique:
            seen_ids.add(row_id)

        amount = row.get("amount")
        if not _valid_amount(amount):
            errors.append({"row": index, "cause": "amount"})
            continue

        unit = row.get("unit", base_unit)
        try:
            known_unit = unit in units
        except TypeError:
            known_unit = False
        if not known_unit:
            errors.append({"row": index, "cause": "unit"})
            continue

        if duplicate:
            errors.append({"row": index, "cause": "duplicate"})
            continue

        records.append({
            "id": row_id,
            "amount": amount * units[unit],
            "unit": base_unit,
        })

    if errors:
        records = []
    return {"ok": not errors, "records": records, "errors": errors}

